package com.library.books.service;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

import org.springframework.stereotype.Service;

import com.library.books.exception.BookNotFoundException;
import com.library.books.model.Book;
import com.library.books.repository.BookRepository;

// Service layer: business logic between controller and repository
@Service
public class BookService {

    private final BookRepository repo;

    public BookService(BookRepository repo) {
        this.repo = repo;
    }

    // (b) add: id is generated by MySQL (AUTO_INCREMENT)
    public Book addBook(Book book) {
        book.setId(null);
        return repo.save(book);
    }

    // (c) all books
    public List<Book> getAllBooks() {
        return repo.findAll();
    }

    // (c) one book, 404 if missing
    public Book getBookById(int id) {
        return repo.findById(id).orElseThrow(() -> new BookNotFoundException(id));
    }

    // (d) update title, author, category, available copies
    public Book updateBook(int id, Book book) {
        getBookById(id);                 // 404 if it doesn't exist
        book.setId(id);
        repo.update(book);
        return book;
    }

    // (e) delete, 404 if missing
    public void deleteBook(int id) {
        getBookById(id);
        repo.deleteById(id);
    }

    // ----- Extra (collections, for the viva) -----

    // List + stream filter: books of one category (case-insensitive)
    public List<Book> getBooksByCategory(String category) {
        return repo.findAll().stream()
                .filter(b -> b.getCategory().equalsIgnoreCase(category))
                .collect(Collectors.toList());
    }

    // Map: category -> total available copies
    // TreeMap sorted A-Z; CASE_INSENSITIVE_ORDER makes "Programming" and "programming" one key
    public Map<String, Integer> copiesByCategory() {
        Map<String, Integer> map = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
        for (Book b : repo.findAll()) {
            map.put(b.getCategory(), map.getOrDefault(b.getCategory(), 0) + b.getAvailableCopies());
        }
        return map;
    }
}
